changeSet.sql:
ALTER TABLE event_registrations ADD CONSTRAINT ck_event_registrations_status
    CHECK (status IN ('registered', 'checked_in', 'withdrawn'));
ALTER TABLE event_registrations ADD CONSTRAINT uq_event_registrations_event_player
    UNIQUE (event_id, player_id);

ALTER TABLE event_queue ADD CONSTRAINT ck_event_queue_match_type
    CHECK (match_type IN ('singles', 'doubles'));
ALTER TABLE event_queue ADD CONSTRAINT ck_event_queue_status
    CHECK (status IN ('waiting', 'matched', 'playing', 'completed', 'skipped', 'left'));
ALTER TABLE event_queue ADD CONSTRAINT fk_event_queue_opponent
    FOREIGN KEY (opponent_queue_id) REFERENCES event_queue(id);

changeSet.rollback:
ALTER TABLE event_queue DROP CONSTRAINT ck_event_queue_match_type;
ALTER TABLE event_queue DROP CONSTRAINT ck_event_queue_status;
ALTER TABLE event_queue DROP CONSTRAINT fk_event_queue_opponent;

changeSet.sql:
ALTER TABLE event_courts ADD CONSTRAINT ck_event_courts_status
    CHECK (status IN ('available', 'playing', 'reserved', 'maintenance'));
ALTER TABLE event_courts ADD CONSTRAINT uq_event_courts_event_number
    UNIQUE (event_id, court_number);

ALTER TABLE matches DROP CONSTRAINT ck_matches_status;
ALTER TABLE matches ADD CONSTRAINT ck_matches_status
    CHECK (status IN ('draft', 'submitted', 'pending_agreement', 'pending_verification', 'verified', 'rejected', 'disputed'));

changeSet.rollback:
ALTER TABLE matches DROP CONSTRAINT ck_matches_status;
ALTER TABLE matches ADD CONSTRAINT ck_matches_status
    CHECK (status IN ('draft', 'submitted', 'pending_verification', 'verified', 'rejected', 'disputed'));

changeSet.sql:
-- Players can see their own registrations
CREATE POLICY event_registrations_select_own ON event_registrations
    FOR SELECT
    USING (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

-- Players can see registrations for public events they're registered to
CREATE POLICY event_registrations_select_event ON event_registrations
    FOR SELECT
    USING (
        event_id IN (
            SELECT id FROM events WHERE visibility = 'public' AND status != 'draft'
        )
        OR fn_is_event_registered(event_id)
        OR fn_is_event_organizer(event_id)
    );

-- Players can register themselves to events
CREATE POLICY event_registrations_insert_own ON event_registrations
    FOR INSERT
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

-- Players can update their own registration (withdraw)
CREATE POLICY event_registrations_update_own ON event_registrations
    FOR UPDATE
    USING (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    )
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

changeSet.rollback:
DROP POLICY IF EXISTS event_registrations_select_own ON event_registrations;
DROP POLICY IF EXISTS event_registrations_select_event ON event_registrations;
DROP POLICY IF EXISTS event_registrations_insert_own ON event_registrations;
DROP POLICY IF EXISTS event_registrations_update_own ON event_registrations;

changeSet.sql:
-- Can see queue if registered to event
CREATE POLICY event_queue_select_registered ON event_queue
    FOR SELECT
    USING (fn_is_event_registered(event_id) OR fn_is_event_organizer(event_id));

-- Can join queue if registered
CREATE POLICY event_queue_insert_own ON event_queue
    FOR INSERT
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
        AND fn_is_event_registered(event_id)
    );

-- Can update own queue entry
CREATE POLICY event_queue_update_own ON event_queue
    FOR UPDATE
    USING (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    )
    WITH CHECK (
        player_id IN (SELECT id FROM player_profiles WHERE user_id = auth.uid())
    );

changeSet.rollback:
DROP POLICY IF EXISTS event_queue_select_registered ON event_queue;
DROP POLICY IF EXISTS event_queue_insert_own ON event_queue;
DROP POLICY IF EXISTS event_queue_update_own ON event_queue;

changeSet.sql:
CREATE POLICY event_courts_select_registered ON event_courts
    FOR SELECT
    USING (fn_is_event_registered(event_id) OR fn_is_event_organizer(event_id));

CREATE POLICY match_score_proposals_select_participant ON match_score_proposals
    FOR SELECT
    USING (fn_is_match_participant(match_id));

CREATE POLICY matches_select_event ON matches
    FOR SELECT
    USING (
        event_id IS NOT NULL AND fn_can_view_event_matches(event_id)
    );

CREATE POLICY events_select_registered ON events
    FOR SELECT
    USING (fn_is_event_registered(id));
